import{z as A,x as B,o as n,c as d,q as i,j as s,D as t,d as E,s as o,S as r,b as a}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"WSD 学习率调度","description":"","frontmatter":{"title":"WSD 学习率调度","date":"2026-09-27T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/wsd-schedule.md","filePath":"llm/wsd-schedule.md","lastUpdated":1791413859000}'),p={name:"llm/wsd-schedule.md"};function c(m,e,D,h,u,C){const l=B("Mermaid");return n(),d("div",null,[e[2]||(e[2]=i('<h1 id="wsd-学习率调度" tabindex="-1">WSD 学习率调度 <a class="header-anchor" href="#wsd-学习率调度" aria-label="Permalink to &quot;WSD 学习率调度&quot;">​</a></h1><div class="epigraph"><p>学习率先爬坡、再恒走、末段骤降——WSD 把退火从尾声提前成一段独立跑道，训中评估从此有了意义。</p><footer>—— 据 MiniCPM（Hu et al. 2024）与 DeepSeek-V2 训练报告；Zhou et al.「Defining Dead Zones」分析</footer></div><p><a href="/llm/lr-schedule">学习率调度</a>把学习率从峰值平滑拖到零，训到一半时模型还悬在半空——中途 checkpoint 既不能部署也难评估。缺口是 <strong>WSD（Warmup–Stable–Decay）</strong>：峰值平台期保住「随时可收工」的可用状态，末段短促退火兑换损失骤降。本课只讲调度形状的选择，不进优化器动力学。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>预算上限定了，但「训到哪一步算够」事先不知道——cosine 需要提前定总步数 \\(T\\)，\\(T\\) 估错则整条曲线作废。团队的现实需求：训中每 1000 步都要有「能拿去评测的模型」。缺口：一种让 checkpoint 永远处于「再训一小段就能退火到可用」状态的调度。</p><p><span class="marginnote">术语翻译：WSD = Warmup-Stable-Decay，三段式调度——warmup 数千步升至峰值 \\(\\eta_{max}\\)，平台期恒定，末段退火到 0 或 \\(\\eta_{max}\\) 的 10%；「10% 退火长度」是经验起点。</span></p><p><span class="marginnote">数字实例：10T token 预算。warmup 2k 步；平台期到 9T token；最后 1T（10%）线性/二次衰减到峰值 10%。平台期内每个 checkpoint 都可在 1T token 内退火——相当于「随时打包」的存款，cosine 只有终点一次。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三段配置：warmup 用线性升到 \\(\\eta_{max}\\)；平台期学习率恒定——这是与 cosine 的本质差异；decay 段选形状（线性、指数、或按 MiniCPM 的「折扣到 10%」）。退火长度经验区间 5–15% 总预算，越短越省但要冒不收敛的险。平台期的副产品：<strong>多次退火探针</strong>——同一平台分别退火可画出「缩放曲线」，MiniCPM 用它对 0.04B–2B 六档小模型各做多次小步退火，据此外推更远训练预算的损失，替代赌一次总预算。</p>',9)),(n(),s(r,null,{default:t(()=>[o(l,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%220%20%E6%AD%A5%22%5D%20--%3E%7C%22%E7%BA%BF%E6%80%A7%20warmup%22%7C%20B%5B%22%E5%B3%B0%E5%80%BC%20%CE%B7_max%22%5D%0A%20%20B%20--%3E%7C%22%E5%B9%B3%E5%8F%B0%E6%9C%9F%3A%20%E6%81%92%E5%AE%9A%22%7C%20C%5B%22%E9%9A%8F%E6%97%B6%E5%8F%AF%E9%80%80%E7%81%AB%22%5D%0A%20%20C%20--%3E%7C%22%E9%80%89%E9%80%80%E7%81%AB%E7%82%B9%20t*%22%7C%20D%5B%22decay%20%E6%AE%B5%205-15%25%20%E9%A2%84%E7%AE%97%22%5D%0A%20%20D%20--%3E%20E%5B%22%E6%94%B6%E6%95%9B%E6%A8%A1%E5%9E%8B%22%5D%0A%20%20C%20--%3E%7C%22%E6%8E%A2%E9%92%88%3A%20%E5%B0%8F%E6%AD%A5%E9%80%80%E7%81%AB%22%7C%20F%5B%22%E9%A2%84%E6%B5%8B%E6%9B%B4%E8%BF%9C%E5%A4%84%E6%8D%9F%E5%A4%B1%22%5D%0A%20%20F%20--%3E%20C%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[E(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=a("p",null,[a("span",{class:"marginnote"},"直觉类比：cosine 是「航班准点起飞准点降落」，起飞前必须定好目的地；WSD 是「巡航飞机」——在巡航高度随便飞，想下就找个机场（退火点）降落，还能先低空盘旋看看（探针退火）再决定飞多远。")],-1)),e[4]||(e[4]=a("h2",{id:"机制",tabindex:"-1"},[E("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[5]||(e[5]=a("p",null,[E("为什么平台期 + 短退火 ≈ cosine 全程？SGD 噪声视角：损失由「期望项 + 梯度噪声方差项」组成，学习率大时噪声项主导、模型在盆地间游走；末段衰减把噪声项压掉，模型落进当前盆地底部。两种调度对「最终损失」的贡献几乎全在 decay 段，平台期只是把「落底位置」的空间探明——于是平台期 checkpoint 的损失高（带噪声）但"),a("strong",null,"参数已在好盆地附近"),E("，短退火即可兑现。这也解释了为何 10% 退火够用：盆地择优（探索）在平台期完成，收敛（兑现）只需短程。")],-1)),(n(),s(r,null,{default:t(()=>[o(l,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%7B%22%E9%AB%98%20%CE%B7%20%E5%9C%A8%E5%B9%B2%E4%BB%80%E4%B9%88%3F%22%7D%20--%3E%20R%5B%22%E5%99%AA%E5%A3%B0%E5%A4%A7%3A%20%E8%B7%A8%E7%9B%86%E5%9C%B0%E6%8E%A2%E7%B4%A2%22%5D%0A%20%20Q%20--%3E%20S%5B%22%E6%8D%9F%E5%A4%B1%E8%A2%AB%E5%99%AA%E5%A3%B0%E9%A1%B9%E6%8A%AC%E9%AB%98%22%5D%0A%20%20R%20--%3E%20T%5B%22%E5%B9%B3%E5%8F%B0%E6%9C%9F%E9%80%89%E5%A5%BD%E7%9B%86%E5%9C%B0%22%5D%0A%20%20S%20--%3E%20U%5B%22checkpoint%20%E5%8F%AF%E7%94%A8%E6%80%A7%E5%B7%AE%3F%22%5D%0A%20%20T%20--%3E%20V%5B%22%E9%80%80%E7%81%AB%E5%8E%8B%E5%99%AA%E5%A3%B0%20%E2%86%92%20%E5%85%91%E7%8E%B0%22%5D%0A%20%20U%20--%3E%20V%0A%20%20V%20--%3E%20W%5B%22%E7%9F%AD%E9%80%80%E7%81%AB%20%E2%89%88%20cosine%20%E7%BB%88%E7%82%B9%22%5D%0A"})]),fallback:t(()=>[...e[1]||(e[1]=[E(" Loading... ",-1)])]),_:1})),e[6]||(e[6]=i('<p><span class="marginnote">常见误区：把平台期学习率调低——平台的意义是保持探索，降 η 等于提前退火、失去「随时收工」；另一误区是退火段中间取 checkpoint 当成品——退火中段的模型往往比平台期更差（噪声没压完、探索已停），要么用完要么别用。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>WSD 的代价：同等预算下平台期损失高于 cosine 中段（噪声税），只在「要训中 checkpoint」或「预算未定」时值回票价。多周期退火（连续 WSD，如 MiniCPM 的多阶段）可复用平台，但每次退火后重升学习率会有损失反弹，反弹幅度随阶段递减。与 <a href="/llm/schedule-free-optimizer">Schedule-Free 优化</a>的接续：后者把「平台 + 退火」内化进优化器迭代点与评估点的分离，连退火决策都省了——但机制理解仍从 WSD 起步。与 AdamW 的配合：\\(\\eta_{max}\\) 按 μP 迁移，平台期与退火段不共用同一套 warmup 判断。</p><p><span class="marginnote">直觉类比：平台期像「把所有抽屉都拉开翻一遍」，退火像「选定抽屉后把手收干净」；cosine 则是从头到尾边翻边收——结果差不多，但 WSD 让你在翻完之前随时可以停下来说「就用这个抽屉」。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>WSD 三段：升、恒、骤降；平台保探索与随时可用，退火兑现损失。</li><li>退火长度 5–15%，探针退火可预测缩放曲线。</li><li>本质是 SGD 噪声项的延迟压除——与 cosine 的差距集中在平台期损失。</li><li>出处：MiniCPM (Hu et al. 2024)；DeepSeek-V2 报告；Zhou et al.「Defining Dead Zones」2024。</li></ul>',6))])}const f=A(p,[["render",c]]);export{_ as __pageData,f as default};
